DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_account` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_password` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_avatar` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_role` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'student',
  `user_phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `union_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mp_open_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT '1',
  `balance` decimal(10,2) NOT NULL DEFAULT '0.00',
  `plan_unlocked` tinyint NOT NULL DEFAULT '0',
  `plan_unlock_time` datetime DEFAULT NULL,
  `last_login_time` datetime DEFAULT NULL,
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_delete` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_account` (`user_account`),
  UNIQUE KEY `user_phone` (`user_phone`),
  UNIQUE KEY `mp_open_id` (`mp_open_id`),
  KEY `idx_user_role_status` (`user_role`,`status`),
  KEY `idx_user_name` (`user_name`),
  KEY `idx_user_phone` (`user_phone`),
  KEY `idx_user_openid` (`mp_open_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户表';

-- ----------------------------
-- Records of user
-- ----------------------------
BEGIN;
COMMIT;

