-- ----------------------------
-- Table structure for user_plan
-- ----------------------------
DROP TABLE IF EXISTS `user_plan`;
CREATE TABLE `user_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `template_id` bigint NOT NULL,
  `test_item_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `score_level` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fitness_level` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `equipment_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `days_per_week` int NOT NULL,
  `snapshot_json` longtext COLLATE utf8mb4_unicode_ci,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `start_date` datetime NOT NULL,
  `end_date` datetime NOT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `is_delete` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_user_plan_user_status` (`user_id`,`status`),
  KEY `idx_user_plan_period` (`start_date`,`end_date`),
  KEY `fk_user_plan_template` (`template_id`),
  CONSTRAINT `fk_user_plan_template` FOREIGN KEY (`template_id`) REFERENCES `plan_template` (`id`),
  CONSTRAINT `fk_user_plan_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户训练计划';

