-- ----------------------------
-- Table structure for user_plan_item
-- ----------------------------
DROP TABLE IF EXISTS `user_plan_item`;
CREATE TABLE `user_plan_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_plan_id` bigint NOT NULL,
  `week_no` int NOT NULL,
  `day_no` int NOT NULL,
  `exercise_id` bigint NOT NULL,
  `sets_count` int DEFAULT NULL,
  `reps_count` int DEFAULT NULL,
  `duration_minutes` int DEFAULT NULL,
  `intensity_note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `completed` tinyint NOT NULL DEFAULT '0',
  `complete_time` datetime DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_delete` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_user_plan_item` (`user_plan_id`,`week_no`,`day_no`,`completed`),
  KEY `fk_user_plan_item_exercise` (`exercise_id`),
  CONSTRAINT `fk_user_plan_item_exercise` FOREIGN KEY (`exercise_id`) REFERENCES `exercise` (`id`),
  CONSTRAINT `fk_user_plan_item_plan` FOREIGN KEY (`user_plan_id`) REFERENCES `user_plan` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户计划动作';

