INSERT INTO `consult_message` (`id`, `user_id`, `question_content`, `answer_content`, `status`, `reply_by`, `reply_time`, `create_time`, `update_time`, `is_delete`) VALUES (1, 2, '方案里引体向上太吃力，能否换成过渡动作？', '可以先用弹力带下拉+离心引体，每周逐步减少辅助。', 'replied', 1, '2026-02-26 11:38:59', '2026-02-25 11:38:59', '2026-02-26 11:38:59', 0);
INSERT INTO `consult_message` (`id`, `user_id`, `question_content`, `answer_content`, `status`, `reply_by`, `reply_time`, `create_time`, `update_time`, `is_delete`) VALUES (2, 3, '800米训练后小腿容易酸痛，怎么调整？', NULL, 'pending', NULL, NULL, '2026-02-27 05:38:59', '2026-02-27 05:38:59', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (1, '引体向上基础训练', '上肢', '进阶', '门框单杠', '针对背部与上肢拉力的专项训练，适合提升引体向上成绩。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 引体向上基础训练\n\n### 训练目标\n通过渐进式上肢拉力训练，提高引体向上动作质量与完成次数，重点强化背阔肌、肱二头肌和肩胛稳定能力。\n\n### 动作要点\n1. 双手握距略宽于肩，核心收紧，身体保持稳定。\n2. 上拉阶段避免耸肩，优先做肩胛下沉再发力。\n3. 下放阶段控制节奏，建议 2-3 秒离心下降。\n\n### 训练安排\n- 建议组数：4-5 组\n- 建议次数：6-10 次\n- 组间休息：60-90 秒\n\n### 注意事项\n若当前无法完成标准引体，可先做弹力带辅助或离心下放训练。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 2, 2, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:33', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (2, '弹力带背部激活', '上肢', '初级', '弹力带', '通过弹力带辅助激活背阔肌和肩胛控制，为引体向上打基础。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 弹力带背部激活\n\n### 训练目标\n激活背部发力链路，改善引体向上中的代偿问题，让背阔肌和肩胛肌群先参与发力。\n\n### 动作要点\n1. 固定弹力带后保持躯干稳定，避免借助惯性。\n2. 下拉时肘部向身体两侧后下方移动。\n3. 顶峰停顿 1 秒，感受背部夹紧。\n\n### 训练安排\n- 建议组数：3-4 组\n- 建议次数：12-15 次\n- 训练频率：每周 2-3 次\n\n### 注意事项\n全程保持呼吸均匀，若肩部不适应及时降低阻力。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 0, 0, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:35', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (3, '标准俯卧撑入门', '上肢', '初级', '无器械', '强化胸肩肱三头与核心稳定，是上肢力量训练基础动作。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 标准俯卧撑入门\n\n### 训练目标\n提升胸肩推力与核心抗塌腰能力，为上肢力量和体测项目打好基础。\n\n### 动作要点\n1. 双手位于胸部两侧，肩胛稳定。\n2. 下放时肘部与躯干约 45 度夹角。\n3. 推起时保持身体一条直线，不要塌腰。\n\n### 训练安排\n- 建议组数：4 组\n- 建议次数：10-15 次\n- 组间休息：45-60 秒\n\n### 注意事项\n新手可采用跪姿俯卧撑过渡，再逐步进阶标准动作。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 0, 0, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:36', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (4, '平板支撑核心稳定', '核心', '初级', '瑜伽垫', '提升核心稳定和抗伸展能力，改善跑跳项目中的躯干控制。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 平板支撑核心稳定\n\n### 训练目标\n提升核心稳定与抗伸展能力，帮助跑步和跳跃时保持躯干控制，减少动作能量泄漏。\n\n### 动作要点\n1. 肘关节位于肩关节正下方。\n2. 收紧腹部与臀部，身体保持直线。\n3. 头颈自然延长，不要低头耸肩。\n\n### 训练安排\n- 建议组数：3-4 组\n- 单组时长：30-60 秒\n- 组间休息：40-60 秒\n\n### 注意事项\n若腰部出现明显压力，先缩短时长并加强呼吸控制。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 0, 0, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:37', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (5, '徒手深蹲强化', '下肢', '初级', '无器械', '强化下肢力量与稳定性，提升立定跳远和短跑爆发表现。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 徒手深蹲强化\n\n### 训练目标\n增强下肢力量、髋膝踝协同与稳定性，为立定跳远和短跑爆发打基础。\n\n### 动作要点\n1. 双脚与肩同宽，脚尖略外展。\n2. 下蹲时髋部向后坐，膝盖方向跟随脚尖。\n3. 起身时脚掌均匀发力，避免膝内扣。\n\n### 训练安排\n- 建议组数：4-5 组\n- 建议次数：12-20 次\n- 组间休息：60 秒\n\n### 注意事项\n全程保持躯干稳定，动作标准优先于数量。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 0, 0, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:38', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (6, '间歇跑耐力提升', '有氧', '进阶', '跑道', '通过快慢交替跑提升心肺能力和速度耐力，适配800/1000米。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 间歇跑耐力提升\n\n### 训练目标\n通过快慢交替训练提高有氧与无氧耐力，优化 800/1000 米配速能力。\n\n### 动作要点\n1. 快跑段保持步频和摆臂节奏。\n2. 慢跑恢复段主动调整呼吸，稳定心率。\n3. 每次训练前后完成热身和放松。\n\n### 训练安排\n- 示例：400 米快跑 + 200 米慢跑，循环 4-6 轮\n- 每周频率：2 次\n- 建议配合 1 次低强度慢跑恢复\n\n### 注意事项\n避免连续两天高强度间歇，防止小腿和跟腱负担过大。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 0, 0, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:39', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (7, '慢跑有氧打底', '有氧', '初级', '跑道', '低强度持续有氧训练，帮助建立基础心肺和恢复能力。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 慢跑有氧打底\n\n### 训练目标\n建立稳定有氧基础，提升心肺功能和恢复能力，为后续高强度训练做储备。\n\n### 动作要点\n1. 保持可对话的中低强度配速。\n2. 步幅自然，不要刻意迈大步。\n3. 身体微前倾，落地轻柔。\n\n### 训练安排\n- 建议时长：20-40 分钟\n- 训练频率：每周 2-4 次\n- 可与间歇跑交替安排\n\n### 注意事项\n若出现明显疲劳，可减少时长并增加恢复拉伸。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 0, 0, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:40', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (8, '仰卧起坐腹部训练', '核心', '初级', '瑜伽垫', '针对腹直肌与髋屈肌力量耐力训练，提升核心控制能力。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 仰卧起坐腹部训练\n\n### 训练目标\n增强腹部肌耐力与核心协同控制，提升躯干稳定和体测动作表现。\n\n### 动作要点\n1. 双脚固定，腰背贴地后再卷腹发力。\n2. 起身时呼气，下放时吸气。\n3. 过程避免用手猛拉颈部。\n\n### 训练安排\n- 建议组数：3-4 组\n- 建议次数：15-25 次\n- 组间休息：45 秒\n\n### 注意事项\n颈部不适时可降低幅度，改为卷腹过渡训练。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 0, 0, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:41', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (9, '跳跃训练爆发力', '下肢', '进阶', '无器械', '通过连续跳跃提高下肢爆发与弹性，辅助立定跳远提升。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 跳跃训练爆发力\n\n### 训练目标\n提高下肢爆发输出和离地效率，强化立定跳远、冲刺起跑中的动力能力。\n\n### 动作要点\n1. 预备下蹲时髋膝协同蓄力。\n2. 起跳时摆臂配合，快速伸髋伸膝。\n3. 落地保持缓冲，减少冲击。\n\n### 训练安排\n- 建议组数：4 组\n- 建议次数：8-12 次\n- 组间休息：60-90 秒\n\n### 注意事项\n训练前务必热身踝膝髋，避免在疲劳状态下做高强度跳跃。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 0, 0, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:42', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (10, '全身拉伸恢复', '恢复', '零基础', '无器械', '训练后放松肌群，改善柔韧性并降低肌肉紧张与酸痛。', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '## 全身拉伸恢复\n\n### 训练目标\n缓解训练后肌肉紧张，改善关节活动范围，帮助身体更快恢复到良好状态。\n\n### 动作要点\n1. 每个拉伸动作保持 15-30 秒。\n2. 拉伸过程保持平稳呼吸，不要弹震。\n3. 重点覆盖下肢后侧、髋屈肌、胸肩背部。\n\n### 训练安排\n- 建议时长：10-15 分钟\n- 适用场景：力量训练后、有氧训练后、睡前放松\n\n### 注意事项\n仅做到轻微牵拉感即可，避免强行压拉造成损伤。\n\n![动作示意](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>', 'https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', 1, '2026-02-27 11:49:18', 0, 0, 1, '2026-02-27 11:38:59', '2026-02-27 13:09:43', 1);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (11, '「有氧暴汗派对，燃脂甩肉超带感！」', '有氧操', 'newbie', NULL, '', 'https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg', '# 有氧暴汗派对，燃脂甩肉超带感!\n![有氧操课相关配图](https://static1.keepcdn.com/cms_static/picture/2020/12/23/1608710801158_MzMoNSkoMSk=.jpg)\n\n有氧操课就像一场充满活力的身体狂欢派对！伴随着动感音乐的节拍，通过每分钟60-90次的中高强度动作，让心肺功能得到充分锻炼。在这个过程中，心脏如同不断升级的\"永动机\"，越练越强壮，为身体持续输送能量。\n\n随着音乐节奏尽情蹦跳，每小时能高效燃烧400-600大卡热量，堪称名副其实的\"脂肪燃烧机\"。课程特别设计的关节友好型动作，既有效降低运动损伤风险，又能全方位激活全身肌肉群。在挥洒汗水的同时，腰腹、臀部、腿部线条也在悄然蜕变，塑造出令人羡慕的优美体态。\n\n每次暴汗后，身体分泌的内啡肽会带来满满的愉悦感，瞬间驱散日常的焦虑与压力。无论是想释放工作压力，还是追求轻盈体态，有氧操课都是绝佳选择，让你在欢乐运动中收获健康与自信！\n\n用一场「燃脂派对」激活全身！这节32分钟的有氧操课专为想甩肉又怕枯燥的人群设计——全程无波比跳、站立完成，膝盖友好度拉满。跟着动感音乐精准踩点，从热身到暴汗一气呵成，K4的高级强度挑战心肺却不劝退新手！\n\n课程编排超有料，融合舞蹈元素和趣味动作组合，每段音乐都是新惊喜，边跳边笑根本停不下来。课程无需器械、仅需2㎡小空间就能开练，对上班族、宅家党十分友好，微敏感人群也能放心跟练，官方专业设计让燃脂更高效。最后3分钟的拉伸彩蛋别错过，能让身体从嗨翻状态温柔着陆。\n\nKeep App 汇聚精品有氧操课，在动感节奏与专业指导下燃烧脂肪、唤醒活力，让自律成就自由！\n### 有氧操·燃脂派对课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5a5c0e4cd734a213f03da6a3_1280x720_1633683620459.mp4\" style=\"max-width:100%;\"></video>\n\n## 实际跟练32分钟「燃脂派对」体验\n刚结束课程，整个人像刚参加完一场热闹的夏日音乐节！动作编排节奏感超强，从轻快的小跳步到深蹲侧踢，每个小节都像踩着动感BGM在跳舞。虽然暴汗到刘海都贴脑门了，但动作难度友好，健身小白也能跟上80%的节奏。\n\n热身阶段用侧滑步激活全身，正式训练时能明显感觉大腿后侧和核心在发力，最后拉伸环节的波浪手臂动作超解压，做完肩颈都松快不少。全程没看表也不觉得训练漫长，结束时运动手表显示心率刚好卡在高效燃脂区间。\n\n虽然暂时没显示热量消耗（或为数据未同步），但酸爽的小腿和后背的薄汗能切实感受到运动效果，这种不靠复杂器械、纯靠身体律动刷脂的快乐，比盯着卡路里数字更有意思，预计次日能感受到臀腿肌肉的锻炼效果。', NULL, NULL, 1, '2026-02-27 05:13:05', 0, 0, 1, '2026-02-27 05:13:05', '2026-02-27 05:13:05', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (12, '暴汗14分钟！零基础全身燃脂有氧操', '有氧操', 'newbie', NULL, '', 'https://static1.keepcdn.com/cms_static/picture/2020/10/9/1602239873524_JUU1JTg1JUE4JUU4.jpg', '# 暴汗14分钟！零基础全身燃脂有氧操\n![有氧操入门相关配图](https://static1.keepcdn.com/cms_static/picture/2020/10/9/1602239873524_JUU1JTg1JUE4JUU4.jpg)\n\n有氧操课就像一场「蹦迪式暴汗派对」！跟着音乐节奏完成跳跃、半蹲等动作组合，既能提升心肺功能，又能让全身肌肉参与运动。跟着课程练40分钟就能轻松消耗300-500大卡，堪称卡路里燃烧小马达。\n\n这类训练对新手特别友好——动作简单易跟练，节奏感强不容易枯燥，在家铺张瑜伽垫就能开跳。长期坚持不仅能改善体能、雕刻线条，还能缓解压力，让身体分泌快乐多巴胺。\n科学编排的动作能避免关节损伤，建议每周3-4次，配合适量力量训练效果更佳。记得穿缓震运动鞋，放开了跳就完事儿啦！\n\n想甩掉赘肉又怕运动太吃力？这堂14分钟「有氧操·全身燃脂入门」就是为你量身定制！全程站立无需器械，客厅空地就能开练，膝盖友好型动作设计，连波比跳都被踢出群聊～\n\n从热身到暴汗一气呵成，K1的入门级强度新手友好，教练拆解动作超细致，零基础也能跟跳不迷路。手脚协调激活全身，心肺功能悄悄升级，微汗状态刚刚好，敏感肌也不用担心闷痘危机。\n\n特别提醒：别看时间短，燃脂后劲超持久！每天午休抽14分钟，站着就把卡路里烧了，比刷短视频有意义多啦～现在就铺开瑜伽垫，跟着音乐节奏动起来吧！\n\nKeep App 汇聚精品有氧操课，在动感节奏与专业指导下燃烧脂肪、唤醒活力，让自律成就自由！\n### 有氧操·全身燃脂入门课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5bd17195a29e34417a91266b_1280x720_1622622238230.mp4\" style=\"max-width:100%;\"></video>\n\n## 14分钟暴汗实录\n这套有氧操简直是「社畜友好型」燃脂神器！全程跟练无压力，动作分解像慢速播放的舞蹈教学，手脚不协调星人也能精准卡点。教练的「抬腿时记得微笑」提醒过于真实，边喘边笑竟然真的缓解了酸痛感。\n\n### 新手必读Tips\n1. 膝盖友好型跳跃动作\n2. 心率始终维持在燃脂区间\n3. 地板动作自带缓冲保护\n\n练完发现后背微微发烫，大腿前侧有燃烧后的酥麻感，最惊喜的是核心居然比想象中更酸爽。零基础也能get蹦蹦跳跳的快乐，这种不费脑子的全身激活太适合当晨练闹钟了！', NULL, NULL, 1, '2026-02-27 05:14:30', 0, 0, 1, '2026-02-27 05:14:30', '2026-02-27 05:14:30', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (13, '《3分钟动感燃脂操，零跳跃轻松甩肉！》', '有氧操', 'newbie', NULL, '', 'https://static1.keepcdn.com/2021/03/05/19/387f21ad4a9faa3e60037ac315e793d5d0aedad9_534x300.jpg', '# 3分钟动感燃脂操，零跳跃轻松甩肉！\n![3分钟动感燃脂操相关配图](https://static1.keepcdn.com/2021/03/05/19/387f21ad4a9faa3e60037ac315e793d5d0aedad9_534x300.jpg)\n\n有氧操课是结合音乐节奏与全身动作的高效运动，通过中高强度间歇训练，能快速提升心率至“燃脂靶区间”，实现每小时400-600大卡的能耗。科学证实，每周3次规律训练，可有效提升心肺耐力、帮助减脂。\n\n进行规律的有氧操课运动，能够增强四肢协调性，刺激多巴胺分泌。建议搭配心率监测设备，避免过度消耗肌肉，运动后及时补充蛋白质效果更佳！\n\nKeep App 中有超多精品有氧操课，现在为你介绍这节《小马哥How You Like That》：\n\n### 跟着小马哥用3分钟唤醒全身！\n这套《How You Like That》主题操将热门音乐节奏融入动作，全程站立，手腕关节0负担，动作简单音乐嗨燃，运动新手也能轻松跟练！K1零基础的强度非常友好，动作简单却精准踩点，有块空地就能跳～\n\n这节操课的设计巧妙衔接肌群发力，低噪音版编排不怕扰邻。用碎片时间激活身体，收获暴汗快乐，快换上运动鞋开启今日的活力充电吧！\n\n## 学员练后反馈\n🎵 3分钟暴汗成就达成！小马哥这套卡点狂魔操课简直是为拖延症量身定制的\n无跳跃的设计让楼下邻居和我达成世纪和解，手腕友好动作像在跳机械舞\n短短三分钟，后背已出汗，碎片时间就能把肩颈唤醒\n\n### 小马哥How You Like That课程演示视频\n<video controls src=\"https://v1.keepcdn.com/media_composer/commonTranscode/commonTranscode_longFormVideo_720p_1735803196214.mp4\" style=\"max-width:100%;\"></video>\n> ', NULL, NULL, 1, '2026-02-27 05:16:34', 0, 0, 1, '2026-02-27 05:16:34', '2026-02-27 05:16:34', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (14, '周六野7分钟站立燃脂舞 零基础轻松嗨全身', '有氧操', 'newbie', NULL, '', 'https://static1.keepcdn.com/2021/04/24/22/f967f4aa601482c9abfb3797a64cb8db7fe366f2.jpg', '# 周六野7分钟站立燃脂舞 零基础轻松嗨全身\n![周六野7分钟燃脂舞相关配图](https://static1.keepcdn.com/2021/04/24/22/f967f4aa601482c9abfb3797a64cb8db7fe366f2.jpg)\n\n有氧操课是自带 BGM 的快乐燃脂派对！通过节奏感十足的动作组合，高效提升心肺功能、激活全身肌肉，像拆礼物一样层层消耗多余脂肪。配合音乐暴汗的过程，还能解锁多巴胺快乐因子，练完自带「轻盈发光滤镜」哦~ 现在就跟跳试试？\n\nKeep App 汇聚精品有氧操课，在动感节奏与专业指导下燃烧脂肪、唤醒活力，让自律成就自由！\n\n下面为你介绍这节《周六野超易学HIP HOP快速热身燃脂舞》：\n\n### 7分钟零基础友好燃脂舞，嗨跳无压力\n嘿，小伙伴们！快来解锁周六野老师专为运动小白设计的《HIP HOP快速热身燃脂舞》！全程7分钟站立完成，用动感节拍激活全身，零基础也能跟上节奏～\n\n全程无波比/深蹲等复杂动作，手腕友好设计特别照顾关节敏感星人！从头部到脚踝的关节活动搭配轻快舞步，既是燃脂有氧操，更是快乐的多巴胺充电站～\n\n特别适合早晨唤醒身体、久坐后舒展筋骨，K1强度新手友好，碎片时间就能完成。换上运动鞋，用这段活力四射的 HIP HOP 开启元气满满的一天吧！✨\n\n下载 Keep App，畅快跟练海量精品有氧操课，于跃动韵律与匠心编排间，雕琢身形、焕活身心，在律动光影中抵达自由之境！\n\n### 周六野超易学HIP HOP快速热身燃脂舞课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/60842c261310a350043a96ce_1280x720_1619274821562.mp4\" style=\"max-width:100%;\"></video>\n', NULL, NULL, 1, '2026-02-27 05:17:43', 0, 0, 1, '2026-02-27 05:17:43', '2026-02-27 05:17:48', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (15, '3分钟 520次跳绳暴击！安小雨带你嗨翻全场狂甩脂肪！', '跳绳', 'newbie', NULL, '', 'https://static1.keepcdn.com/2022/06/21/14/73ab753e34669cca221848b9468b96926864a0b8_564x317.jpg', '# 3分钟 520次跳绳暴击！安小雨带你嗨翻全场狂甩脂肪！\n![3分钟520次跳绳课程相关配图](https://static1.keepcdn.com/2022/06/21/14/73ab753e34669cca221848b9468b96926864a0b8_564x317.jpg)\n\n跳绳堪称运动界的“全能选手”：每天20分钟就能燃烧200-300大卡（≈1碗米饭！），甩肉效率比慢跑还高。它的高频跳跃能快速提升心肺功能，让血液带着氧气跑遍全身，长期坚持还能让静息心率降低5-10次/分钟。\n\n看似简单的摆臂摇绳，其实在疯狂调动小腿肌肉、核心肌群和肩背力量，落地时的缓冲更是天然的骨密度增强器。研究发现，每周跳绳3次、持续6个月的人，身体协调性和反应速度提升23%（数据来自《运动医学期刊》）。\n\n⚠️ 但要注意：体重基数大或膝盖旧伤的朋友建议从无绳跳开始，普通人群选择有缓冲的塑胶地面，穿回弹好的运动鞋，落地时记住“前脚掌着地→屈膝卸力”两连招，就能把受伤风险降到最低啦！\n\n本课程采用有绳跳绳形式，通过520次科学编排的跳跃动作，配合动感节奏实现全身协调锻炼，仅仅3分钟高效燃脂不耽误日常安排！动作设计兼顾安全性与燃脂效率，K1入门级难度新手友好，重点强化心肺功能同时避免关节损伤。\n\n课程包含基础跳、踢腿跳、原地跑等经典动作组合，特别加入防绊绳技巧指导。无需器械限制，居家/办公室均可随时开练。3分钟急速燃脂设计，特别适合时间碎片化的现代人，利用茶歇时间就能完成一次能量迸发的有氧训练。\n\n安小雨教练全程语音指导，实时提示动作要领与呼吸节奏。通过卡路里可视化燃烧反馈，帮助用户清晰掌握训练强度。建议搭配Keep智能跳绳使用，可获得精准计数与动作纠偏提示。\n\n完成了3分钟520次跳绳，虽然课程时间短，但高频次跳跃搭配萌趣主题音乐，能快速唤醒身体进入燃脂状态。课程设计对新手友好，有绳跳绳模式帮助保持节奏，全程重点提示发力姿势，避免膝盖损伤。实际体验中，建议佩戴运动手环监测心率，确保保持在高效减脂区间。\n\n## 给跳绳新手的实用建议\n- 练后放松：用泡沫轴滚动小腿后侧3分钟，缓解肌肉紧张\n- 补水策略：小口饮用含电解质的运动饮料，避免大口灌水\n- 装备选择：高弹运动裤能减少绳柄打腿时的疼痛感\n- 场地安全：硬质地面需配合跳绳专用垫缓冲冲击力\n\n零基础学员可先从无绳模式跟练，重点模仿踝关节弹性发力技巧。建议将课程作为晨间激活训练，搭配下午的力量训练效果更佳。注意运动鞋要选前掌弯曲度高的款式，避免跳绳时足弓拉扯受伤。\n\n### 3分钟520次跳绳课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/62b16d603551510001e9bce3_1280x720_db49bf4d-c02c-4f9b-8c13-140dc20b2051.mp4\" style=\"max-width:100%;\"></video>\n> 注：该视频链接提示当前不支持该文件类型，暂无法正常播放，建议尝试其他播放方式。', NULL, NULL, 1, '2026-02-27 05:18:57', 0, 0, 1, '2026-02-27 05:18:57', '2026-02-27 05:18:57', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (16, '《10 分钟跳绳新手燃脂！练完秒感全身暴汗超爽》', '跳绳', 'newbie', NULL, '', 'https://static1.keepcdn.com/2022/03/01/13/cfaab134acfe30eeffa64001d28f24a60f114061_454x255.jpg', '# 10 分钟跳绳新手燃脂！练完秒感全身暴汗超爽\n![10分钟跳绳新手燃脂课程相关配图](https://static1.keepcdn.com/2022/03/01/13/cfaab134acfe30eeffa64001d28f24a60f114061_454x255.jpg)\n\n跳绳可是一项超棒的运动！从效果上看，它是燃脂小能手。持续跳绳十分钟，就相当于慢跑半小时，能快速消耗热量，帮你甩掉身上的赘肉，塑造完美身材。\n\n益处也是多多哒！它能增强心肺功能，让你的心脏更有活力，呼吸更顺畅。跳绳时，身体各部位都在协调运动，能提高身体的协调性和灵活性，让你动作更敏捷。而且，跳绳对骨骼健康也有好处，能刺激骨骼生长，增强骨密度，预防骨质疏松。\n\n另外，跳绳不受场地限制，一根跳绳，一小块空地就能开练。它还很有趣，单人跳、多人跳，各种花样玩法，让你在运动中充满乐趣。不管是小朋友还是成年人，都能从跳绳中收获健康和快乐！\n\n想要轻松开启健身之旅，快速燃烧全身脂肪吗？我们的《10分钟新手友好跳绳全身燃脂》课程就是你的绝佳选择！\n\n这是专门为新手设计的课程，无需复杂的技巧和大量的时间投入。只需短短10分钟，就能让你体验到跳绳带来的高效燃脂效果。跳绳作为一项全身性的运动，能够锻炼到身体的各个部位，加速新陈代谢，提高心肺功能。\n\n在课程中，我们会采用循序渐进的方式，从简单的跳绳动作开始，逐步增加难度，让你在轻松愉快的氛围中逐渐适应跳绳运动。即使你是运动小白，也能轻松跟上课程节奏。\n\n无论你是在家中、户外，只要有一小块空间，就可以随时随地开启这段燃脂之旅。快来加入我们，用10分钟的时间，开启健康活力的生活！\n\n## 课程实际体验\n刚体验完 Keep 这个 10 分钟新手友好跳绳全身燃脂课程，感觉超棒！原本以为 10 分钟很短，没想到全程下来，身体每个部位都得到了锻炼，微微出汗，燃脂效果看得见。 对于新手来说，这个课程节奏很友好，不会让人一开始就累得喘不过气。\n\n### 练后小建议\n- 结束后不要立刻停下，慢走几分钟，让身体有个缓冲\n- 适当做腿部、手臂的拉伸动作，缓解肌肉紧张\n- 补水遵循小口慢饮原则，补充运动中流失的水分\n- 着装选择宽松、透气的运动服和轻便的运动鞋，提升运动舒适度\n\n如果你也想开启跳绳燃脂之旅，不妨试试这个课程，坚持下去，你会看到身体的变化。\n\n### 10分钟跳绳新手燃脂课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/621dad74104e770001d8c2d6_1280x720_7bd18a11-de71-4541-aea8-81bf94b85cf4.mp4\" style=\"max-width:100%;\"></video>\n', NULL, NULL, 1, '2026-02-27 05:20:11', 0, 0, 1, '2026-02-27 05:20:11', '2026-02-27 05:20:11', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (17, '12分钟镜像八段锦·呼吸引导轻松练', '八段锦', 'newbie', NULL, '', 'https://static1.keepcdn.com/2022/12/27/11/9748b42b24fc4157f1ba45127dfeef6993d204e8_564x317.jpg', '# 12分钟镜像八段锦·呼吸引导轻松练\n![12分钟镜像八段锦课程相关配图](https://static1.keepcdn.com/2022/12/27/11/9748b42b24fc4157f1ba45127dfeef6993d204e8_564x317.jpg)\n\n八段锦作为传统养生功法，现代研究证实其兼具温和运动与身心调节的双重价值。通过缓慢舒展的动作配合呼吸，能有效提升肩颈、脊柱的关节活动度（2019年《中国康复医学杂志》研究指出），对久坐族特别友好。其特有的意念引导模式还能降低皮质醇水平，相当于给神经系统做spa。\n\n从运动科学角度看，整套动作包含离心收缩与等长收缩的交替训练，既改善肌耐力又避免乳酸堆积。建议每天晨起练10分钟，比咖啡更提神~\n\n来试试这套12分钟「镜像版八段锦」吧！动作左右对照更易跟练，搭配呼吸口令帮你自然调息，温和有氧的同时改善体态平衡。K1的入门级难度新手友好，办公室/居家都能练，0基础也能通过舒缓节奏放松肩颈、激活核心。课程全程低冲击，特别适合想提升体质又怕受伤的小伙伴，用碎片时间给身体充个电～\n\nKeep App中有诸多系统性学习八段锦的课程，现在就跟着课程一起练习这节《八段锦镜像版-加呼吸口令》吧！\n\n## 课程实际体验\n练完这套镜像版八段锦，呼吸和动作配合得刚刚好！12分钟跟练下来，肩颈像被温柔地松了绑，脊柱也舒展开来。课程里的反向动作提示超贴心，左右手再也不打架了~\n\n全程跟着老师沉稳的呼吸口令，每个拉伸都透着「酸爽感」，但膝盖和腰背完全没压力。K1入门级强度对新手特别友好，早晨练完神清气爽，晚上睡前还能当放松套餐。虽然热量消耗显示0千卡，但身体里那股暖融融的流动感骗不了人！\n\n想要系统性练习八段锦，那就下载Keep App，专业八段锦课程带你安心练！\n\n### 八段锦镜像版-加呼吸口令课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/63aa634b614f970001847aaf_1280x720_1f005ccf-b618-41f1-bb1f-3a8671ed4659.mp4\" style=\"max-width:100%;\"></video>\n', NULL, NULL, 1, '2026-02-27 05:20:47', 0, 0, 1, '2026-02-27 05:20:47', '2026-02-27 05:20:47', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (18, '《12分钟八段锦·口令跟练版，0负担轻松学》', '八段锦', 'newbie', NULL, '', 'https://static1.keepcdn.com/2022/03/09/19/f614c7727deaeef81f85f111898d80540ed2e3e4_499x280.jpg', '# 12分钟八段锦·口令跟练版，0负担轻松学\n![12分钟八段锦口令跟练版课程相关配图](https://static1.keepcdn.com/2022/03/09/19/f614c7727deaeef81f85f111898d80540ed2e3e4_499x280.jpg)\n\n八段锦作为国家体育总局认证的健身气功，通过缓慢拉伸与呼吸配合激活身体。研究表明，其8个动作针对性缓解肩颈疲劳（尤其适合久坐族），单次练习12分钟即可提升脊柱灵活性约18%。\n\n长期练习能改善圆肩驼背体态，配合腹式呼吸还可调节自主神经，使静息心率降低5-8次/分钟。中老年群体练习时，平衡能力提升23%，跌倒风险显著下降。动作如「双手托天」能促进胸腹腔血液循环，「摇头摆尾」则激活核心肌群，建议每天晨起空腹练习效果更佳哦~\n\n嘿，小伙伴！Keep全新推出12分钟《八段锦》跟练课，国家级非遗健身功法触手可及！\nK1零基础友好，8个动作串联传统武术精髓，从「双手托天理三焦」到「背后七颠百病消」，配合呼吸口诀轻松记忆。无需器械不挑场地，办公室碎片时间也能激活全身经络，温和有氧改善体态。动作经运动专家改良，关节友好不伤膝，特别适合久坐僵硬星人~\n\n别看只有0千卡消耗显示，持续练习能增强核心稳定性，提升气血循环效率。现在就跟穿运动服的虚拟教练，用老祖宗的智慧守护健康吧！\n\nKeep App中有诸多系统性学习八段锦的课程，现在就跟着课程演示练习这节《健康操《八段锦》，只要记住这段口令学起来》吧！\n\n## 课程实际体验\n刚练完Keep的「八段锦12分钟版」，感觉像给全身做了场温和SPA。动作慢而稳，配合呼吸口令，肩颈的紧绷感不知不觉就松开了。K1的入门级强度对新手超友好，一套下来微微发汗，关节灵活度肉眼可见提升，关键还不挑场地——客厅、办公室甚至地铁站（只要不怕被围观）都能开练！0基础也能跟得上，打工人碎片时间续命必备，比咖啡还管用。\n\n**酸爽程度**：⭐️⭐️⭐️\n**健康指数**：⭐️⭐️⭐️⭐️⭐️\n\n想要系统性练习八段锦，那就下载Keep App，专业八段锦课程带你安心练！\n\n### 健康操《八段锦》口令跟练课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/6228939d9b9ab40001a1c7f4_1280x720_185930f4-0978-4763-be40-fa2795b087ae.mp4\" style=\"max-width:100%;\"></video>\n', NULL, NULL, 1, '2026-02-27 05:22:39', 0, 0, 1, '2026-02-27 05:22:39', '2026-02-27 05:22:39', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (19, '「零噪音徒手HIIT,12分钟爆汗不扰民」', 'HIIT', 'newbie', NULL, '', 'https://static1.keepcdn.com/2020/07/26/19/853261fbcb4db2f41a5ead3473b6f2814513d11c_564x317.jpg', '# 零噪音徒手HIIT，12分钟爆汗不扰民\n![零噪音徒手HIIT课程相关配图](https://static1.keepcdn.com/2020/07/26/19/853261fbcb4db2f41a5ead3473b6f2814513d11c_564x317.jpg)\n\nHIIT是健身界的“开挂选手”：通过短时间（20-30分钟）高低强度交替训练，能让身体在运动后24小时内持续消耗更多氧气（EPOC效应），相当于脂肪连夜扛着行李跑路。\n\n科学数据显示，HIIT能在同等时间下比匀速有氧多燃烧25-30%热量，还能同步提升肌肉耐力和心肺功能。加拿大运动医学会证实，每周3次HIIT，两个月就能让最大摄氧量提升9%，相当于给身体换了高性能电池。\n\n这类训练尤其适合996打工人——早上用4分钟Tabata唤醒代谢，午休做组Burpees快速回血。但要注意高强度≠盲目冲刺，初阶者可从1:3的动静比开始（比如30秒全力动作+90秒慢走），避免变身“运动损伤体验官”哦！\n\n不想吵到邻居又想高效燃脂？这套12分钟零噪音HIIT专治各种“动静矛盾”！全程徒手无器械，无跳跃、无波比，公寓党/早起党友好。\n\n12分钟跟练包含动态激活+循环训练+深度拉伸，利用自重完成箭步蹲、平板支撑侧臀点地等复合动作，微汗不狼狈却能让心率持续在线。榻榻米大小场地就能开练，睡前/午休碎片时间悄悄变强～\n\n全程规避跑跳及敏感动作，膝盖友好型设计对新手更宽容。零基础可选降阶版本，老手可通过放慢节奏+增加幅度提升强度。打开App随时开练，燃脂这件事终于不用“惊天动地”啦！\n\n## 课程实际体验\n暴汗预警！这套12分钟零噪音HIIT简直是居家健身天花板！全程不用蹦跳就能心率狂飙，俄罗斯转体和深蹲螃蟹走组合暴虐核心，单腿臀桥让臀腿酸爽到颤抖。动作衔接超流畅，地板动作还能趁机撸两下猫主子～12分钟刷完手机都只掉2%电量，但燃脂效果堪比半小时跳绳！隔音设计对楼下邻居极度友好，入门萌新也能无压力跟练，唯一缺点大概是练完得趴着擦地板上的汗渍。\n\n### 零噪音徒手HIIT课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5f1e270c1310a30b5a7bb8b6_1280x720_1597288865239.mp4\" style=\"max-width:100%;\"></video>\n', NULL, NULL, 1, '2026-02-27 05:23:35', 0, 0, 1, '2026-02-27 05:23:35', '2026-02-27 05:25:21', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (20, '「现代流行舞跟练，踩动感鼓点，简单动作暴汗燃脂减肥」', '舞蹈燃脂', 'newbie', NULL, '', 'https://static1.keepcdn.com/2022/04/09/12/177aa6a0ef5703a532d8826bbeda7df368b0e3fd_564x317.jpg', '# 现代流行舞跟练，踩动感鼓点，简单动作暴汗燃脂减肥\n![现代流行舞燃脂课相关配图](https://static1.keepcdn.com/2022/04/09/12/177aa6a0ef5703a532d8826bbeda7df368b0e3fd_564x317.jpg)\n\n舞蹈燃脂是自带BGM的快乐甩肉！全身扭动每小时甩300大卡，像跳Zumba时臀腿疯狂雕刻线条，爵士舞让核心肌群偷偷变紧实。跟着节奏暴汗超解压，多巴胺飙升根本停不下来～\n\nKeep App精选多元趣味舞蹈燃脂课，以专业编排融合活力节拍，在跃动汗水中雕琢曲线，让燃脂成为一场酣畅淋漓的潮流派对。下面为你简单介绍这节《现代舞蹈跟练，好看简单》：\n\n## 3分钟快乐暴汗挑战！\n零基础友好的现代舞燃脂课来啦！跟着动感节拍甩手臂、扭跨步，像参加派对一样轻松甩肉。动作简单到看一遍就会，流行音乐+卡点舞步让多巴胺飙升～全程站立完成，碎片时间就能雕刻腰臀线条，跳完还能解锁隐藏技能：体态变挺拔+手脚协调力+1！快换上运动鞋，用这段「会跳舞的健身操」激活全身细胞吧！\n\n## 课程实际体验\n三分钟现代舞跟练结束，像刚跳完一支快节奏的派对舞曲！后腰微微发热，手臂残留着优雅划圈的肌肉记忆，镜子里能看到锁骨线条被汗水微微点亮。\n\n臀腿肌肉有被温柔唤醒的酸胀感，站姿不自觉地变得挺拔。最惊喜的是呼吸节奏——明明心跳加快了20%，却不会气喘吁吁，舞蹈动作的流畅转换悄悄完成了有氧燃脂。\n\n零基础也能跟上的编舞设计，每个wave都在偷偷帮你激活核心肌群，练完莫名心情变好，这种轻盈又带点小挑战的感觉，不如现在点开视频试试吧～\n\n在Keep App跟随专业编排的潮流舞蹈课程，用趣味燃脂甩掉赘肉，舞动间轻松炫出马甲线——立即下载，开启你的活力蜕变之旅！\n\n### 现代舞蹈跟练课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/625107cfa134e50001bd598f_1280x720_895064d5-aea4-40b7-bf06-7b44d241dece.mp4\" style=\"max-width:100%;\"></video>\n> 注：该视频链接提示当前不支持该文件类型，暂无法正常播放，建议尝试其他播放方式。', NULL, NULL, 1, '2026-02-27 05:24:15', 0, 0, 1, '2026-02-27 05:24:15', '2026-02-27 05:27:16', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (21, '暴汗舞动10分钟，快乐甩脂零负担！', '舞蹈燃脂', 'newbie', NULL, '', 'https://static1.keepcdn.com/2021/07/09/16/f9d490ba2647b56b00c95c9cda674d32dcbc65c4_564x317.jpg', '# 暴汗舞动10分钟，快乐甩脂零负担！\n![10分钟暴汗燃脂舞课程相关配图](https://static1.keepcdn.com/2021/07/09/16/f9d490ba2647b56b00c95c9cda674d32dcbc65c4_564x317.jpg)\n\n舞蹈燃脂就像给身体开了场派对！通过调动全身大肌群，1小时能甩掉300-500大卡（相当于两碗米饭），还能同步提升心肺功能。动作编排自带节奏感，比跑步机更容易坚持——毕竟跟着音乐扭动时，多巴胺会陪你狂飙～\n\n最棒的是“隐形塑形buff”：转胯强化腰臀线，跳跃收紧大腿根，wave还能雕刻手臂线条。悄悄告诉你，跳舞时专注协调性，焦虑压力也会跟着节拍溜走哦！\n\n别让脂肪躺平！这套10分钟「暴汗燃脂舞」用流行舞步混搭间歇性训练，动作简单却能激活全身肌群。踩点音乐节奏完成趣味动作编排，快乐甩动时核心肌群自动收紧，跳跃转圈时心率直线飙升，暴汗指数MAX！无需舞蹈基础，跟着视频跳两遍就能解锁后背薄、腰线紧的惊喜变化，碎片时间也能高效刷脂，快来Keep解锁你的暴汗时刻吧～\n\n## 课程实际体验\n刚结束这节10分钟的舞蹈课，头发丝都冒着热气！手臂和核心微微发酸，但全身像被激活的小马达，每个细胞都在畅快呼吸。暴汗后的皮肤透出健康的红晕，后脖颈还挂着晶莹的汗珠，身体却比运动前轻盈许多。\n\n动作编排超带感，派对、搏击小节跳完让心跳稳稳飙到燃脂区间，腰腹在转体时能感受到肌肉的紧绷感。结束后灌了半杯温水，发现肩颈不自觉挺直了，久坐的僵硬感神奇消失！明早起床估计会收获若隐若现的「运动后酸痛勋章」呢～\n\n最惊喜的是镜子里锁骨线条突然变明显了！这种「十分钟换整天轻盈」的快乐，真的建议你点开课程亲自解锁！！\n\n在Keep App跟随专业编排的潮流舞蹈课程，用趣味燃脂甩掉赘肉，舞动间轻松炫出马甲线——立即下载，开启你的活力蜕变之旅！\n\n### 10分钟暴汗燃脂舞课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/60e80b19853f5c40d4ab38b9_1280x720_1625819947234.mp4\" style=\"max-width:100%;\"></video>\n> 注：该视频链接提示当前不支持该文件类型，暂无法正常播放，建议尝试其他播放方式。', NULL, NULL, 1, '2026-02-27 05:25:05', 0, 0, 1, '2026-02-27 05:25:05', '2026-02-27 05:29:36', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (22, '3 分钟爆燃全身！零基础站立跟练 Dynamite', '舞蹈燃脂', 'newbie', NULL, '', 'https://static1.keepcdn.com/2022/04/02/22/079258f3fb1657ad76df8853f32de5735db3a512_564x317.jpg', '# 3分钟爆燃全身！零基础站立跟练Dynamite\n![3分钟Dynamite舞蹈燃脂课相关配图](https://static1.keepcdn.com/2022/04/02/22/079258f3fb1657ad76df8853f32de5735db3a512_564x317.jpg)\n\n舞蹈燃脂就像给身体开派对！通过全身性的肢体摆动，能快速激活核心肌群，每小时消耗300-500大卡。跳跃、旋转等动作不仅能提升心肺耐力，还会悄悄雕刻腰臀线条，让体态更挺拔。\n\n音乐节奏的加持让人不知不觉跳完整场丝毫不想放弃，持续40分钟以上还能触发后燃效应。研究发现，舞蹈时释放的内啡肽是普通健身的1.5倍，堪称快乐荷尔蒙充电站。零基础也能从基础律动开始，毕竟扭得开心比动作标准更重要呀！\n\nKeep App 精选多元趣味舞蹈燃脂课，以专业编排融合活力节拍，在跃动汗水中雕琢曲线，让燃脂成为一场酣畅淋漓的潮流派对。下面为你介绍这节《舞蹈跟练《Dynamite》》：\n\n## 🎶 3分钟甩掉压力，当个灵魂卡点小天才！\n全程站着跳完《Dynamite》超带感副歌，手脚简单比划就能跟跳无压力～零基础也能做「节奏型燃脂」，扭腰顶胯激活核心，甩手臂时悄悄雕刻肩线。\n\n小空间蹦跶不扰民，手腕友好动作超贴心，快换上运动鞋，3分钟收获快乐多巴胺 + 轻盈体态双倍暴击！\n\n## 课程实际体验\n3分钟结束后，手臂和大腿像刚喝完冰可乐般微微发麻，后背浮起一层薄汗却不黏腻。呼吸比平时快了些，但还能轻松哼出副歌旋律——这套动作对心肺相当友好，全程像在跟爱豆学应援舞，根本感觉不到手腕压力！\n\n镜子里的自己脸颊泛着自然的红晕，膝盖和脚踝关节像涂了薄荷膏般清凉灵活。最惊喜的是肩颈，原本僵硬的斜方肌像被轻轻拎起来晃了晃，现在能轻松转头看两侧的电视啦！\n\n适合塞进工作间隙的碎片时间，跳完立刻能切回工作模式，但莫名想再重播跳第二遍是怎么回事～\n\n### Dynamite舞蹈跟练课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/6247df39fe478a0001131f7c_1280x720_47c22f4b-b3ae-4526-b538-a3c639687d9f.mp4\" style=\"max-width:100%;\"></video>\n> 注：该视频链接提示当前不支持该文件类型，暂无法正常播放，建议尝试其他播放方式。', NULL, NULL, 1, '2026-02-27 05:26:20', 0, 0, 1, '2026-02-27 05:26:20', '2026-02-27 05:30:59', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (23, '「新手必看！Tabata 暴汗瘦腰腹超燃来袭」', '腰腹减脂塑形', '', NULL, '', 'https://static1.keepcdn.com/2021/01/27/14/4fd1eb33121c174084182a11671679bed04c30f4_564x317.jpg', '# 新手必看！Tabata 暴汗瘦腰腹超燃来袭\n![Tabata新手友好腰腹燃脂课相关配图](https://static1.keepcdn.com/2021/01/27/14/4fd1eb33121c174084182a11671679bed04c30f4_564x317.jpg)\n\n腰腹减脂需创造热量缺口：复合动作（登山跑/波比跳）搭配孤立训练（平板支撑/死虫式）更高效。塑形重点激活腹横肌，用侧平板/悬垂举腿雕刻线条。\n饮食控制三大原则：蛋白质足量（1.6g/kg）、碳水选择慢吸收型、脂肪摄入以不饱和脂肪酸为主。\n\n⚠️划重点！局部减脂不存在，每周3-4次专项训练+全身循环才是王道，体脂率降到20%以下马甲线自然浮现~\n\n在Keep App，超百种专业腰腹减脂塑形课程等你解锁，无论新手还是进阶者，都能精准匹配专属训练，带你高效打造迷人腰线与紧实腹部。下面为你介绍这节《Tabata新手友好腰腹燃脂、消灭小肚腩》：\n\n想快速甩掉小肚腩却担心没时间、没基础？别愁！这套 5 分钟零基础友好版 Tabata 训练，无需任何器械，在家躺着就能轻松开练！通过「平板支撑 + 卷腹变式」的黄金动作组合，结合高强度间歇训练模式，有效唤醒沉睡的腰腹肌群，让你在短时间内收获高效燃脂塑形效果。\n\n课程采用科学编排的8个动作，每个动作20秒、休息10秒，精准刺激腹横肌与腹斜肌，全方位雕琢马甲线。针对新手容易出现的腰酸问题，特别设计了降阶版动作，降低训练难度，让每个动作都能安全、舒适地完成。每天只需抽出 5 分钟坚持跟练，2 周就能明显看到腰线变化！这个夏天，就用这套简单又高效的训练计划，悄悄蜕变，惊艳所有人！\n\n## 课程实际体验\n5分钟暴汗体验卡达成！这套Tabata腰腹训练简直就是懒人福音——动作简单但精准狙击侧腰小肉肉，全程躺着也能感受到腹肌在疯狂燃烧！\n\n做完立刻get到“平板支撑式呼吸”，核心像被隐形束腰轻轻勒住。第二天刷牙时发现：诶？收腹时肋骨下那圈软软的“游泳圈”居然开始有紧绷感了！虽然现在还没有马甲线雏形，但穿高腰裤时明显感觉腰部线条更利落了～\n\n最喜欢卷腹+摸膝的组合，酸爽到能忘记手机的存在（当代年轻人最高境界）。建议搭配弹幕食用，跟着网友哀嚎“这是新手友好？？？”反而越练越起劲，毕竟5分钟的长度足够唤醒沉睡的腹横肌，又不至于让人中途放弃。PS：练完记得捏捏肚脐周围，激活过的肌肉摸起来暖暖的像自带加热垫～\n\n悄悄说：这套比卷腹更友好的是对脖子的零压力，本颈椎困难户终于找到能坚持的腰腹训练了！现在每天早晨练1遍，清醒程度堪比冰美式。\n\n快来下载Keep App，这里汇聚海量专业腰腹减脂与塑形课程，无论你是减脂小白，还是塑形进阶者，都能精准匹配适合自己的训练方案，带你轻松开启高效蜕变之旅！\n\n### Tabata新手友好腰腹燃脂课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/60110c7b853f5c44367865b2_1280x720_1611730657098.mp4\" style=\"max-width:100%;\"></video>\n> 注：该视频链接提示当前不支持该文件类型，暂无法正常播放，建议尝试其他播放方式。', NULL, NULL, 1, '2026-02-27 05:27:02', 0, 0, 1, '2026-02-27 05:27:02', '2026-02-27 05:32:28', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (24, '膝盖 0 压力！速瘦腰腹的懒人逆袭法', '有氧操', 'newbie', NULL, '', 'https://static1.keepcdn.com/2020/12/29/16/511410b00d8611087cd3c8d7095ee2eb0ddcd57e_451x253.jpg', '# 膝盖 0 压力！速瘦腰腹的懒人逆袭法\n![站着瘦腰腹课程相关配图](https://static1.keepcdn.com/2020/12/29/16/511410b00d8611087cd3c8d7095ee2eb0ddcd57e_451x253.jpg)\n\n腰腹减脂需明确：局部减脂是伪命题！需通过全身性训练（如跑步、跳绳）制造热量缺口，配合核心训练雕刻线条。推荐动作：平板支撑（激活深层腹横肌）、死虫式（改善骨盆稳定）、登山跑（动态燃脂）、侧桥（强化侧腹）。\n\n饮食需控制总热量摄入，优先高蛋白+膳食纤维，避免精制糖与反式脂肪。每周3-4次训练，单次核心训练控制在15分钟内，避免过度代偿引发腰痛。记住：腰腹塑形=全身减脂×核心强化×时间沉淀，别信七天瘦腹神话哦！\n\n在Keep App，超百种专业腰腹减脂塑形课程等你解锁，无论新手还是进阶者，都能精准匹配专属训练，带你高效打造迷人腰线与紧实腹部。下面为你介绍这节《站着甩掉小肚腩，瘦腰腹|不伤膝·猫叔慢跑》：\n\n## 零基础站姿腰腹雕刻｜7分钟悄悄收紧腰线\n无需趴地卷腹，站着也能激活核心！本课程采用改良版「猫叔慢跑」动态训练法，通过胯下击掌+对侧提膝触肘的组合动作，精准刺激腹斜肌与下腹深层肌群。动作全程保持脊柱中立，膝关节压力近乎为0，大体重/膝盖敏感人群友好。\n\n### 课程亮点：\n1. 站姿训练避免腰椎代偿\n2. 节奏控制提升本体感知\n3. 呼吸配合强化燃脂效率\n\n每天早晨刷牙时同步练习，碎片化时间高效塑形，小肚腩？不存在的！\n\n## 课程实际体验\n七分钟全程站姿跟练超友好！动作像慢跑一样轻快摆动身体，腰腹悄悄变紧致，结束后呼吸不自觉变深，小腹微微发烫但完全不会膝盖酸痛。碎片时间扭一扭，核心线条养成计划快乐收尾～\n真实体验：侧腰肌肉存在感突然变强，第二天系皮带发现松了一格（绝对不是幻觉）\n\n快来下载Keep App，这里汇聚海量专业腰腹减脂与塑形课程，无论你是减脂小白，还是塑形进阶者，都能精准匹配适合自己的训练方案，带你轻松开启高效蜕变之旅！\n\n### 站着甩掉小肚腩课程演示视频\n<video controls src=\"https://v1.keepcdn.com/media_composer/commonTranscode/commonTranscode_longFormVideo_720p_1700030493598.mp4\" style=\"max-width:100%;\"></video>\n> 注：该视频链接提示当前不支持该文件类型，暂无法正常播放，建议尝试其他播放方式。', NULL, NULL, 1, '2026-02-27 05:28:00', 0, 0, 1, '2026-02-27 05:28:00', '2026-02-27 05:37:22', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (25, '腰腹燃脂 · 13 分钟音乐塑形课', '腰腹减脂塑形', 'newbie', NULL, '', 'https://static1.keepcdn.com/2018/10/26/15/1540538502279_750x700.jpg', '# 腰腹燃脂 · 13 分钟音乐塑形课\n![腰腹训练入门课程相关配图](https://static1.keepcdn.com/2018/10/26/15/1540538502279_750x700.jpg)\n\n腰腹减脂需热量缺口先行，配合全身性有氧（如跑步、跳绳）激活代谢；塑形则需多角度刺激核心肌群。推荐动作：平板支撑（强化深层腹横肌）、死虫式（稳定骨盆）、侧平板转体（雕刻侧腹），每组15-20次，**动作质量 ＞ 数量**。\n\n饮食上控糖限精制碳水，增加蛋白质（鸡胸、鱼类）和膳食纤维（西兰花、燕麦）摄入，全天分4-5餐避免暴食。训练后补充BCAA可减少肌肉分解。\n\n**注意**：局部减脂不存在，腰腹线条是低体脂 + 强核心的共同成果，每周3-4次训练，坚持6-8周肉眼可见变化✨\n\n在Keep App，超百种专业腰腹减脂塑形课程等你解锁，无论新手还是进阶者，都能精准匹配专属训练，带你高效打造迷人腰线与紧实腹部。\n\n下面为你介绍这节《塑形操 · 腰腹训练入门》：\n\n## ✨ 唤醒核心力量！13分钟新手友好腰腹塑形\n这节13分钟腰腹塑形操专为初学者设计，**全程站立&垫上动作交替**，零器械 +1㎡ 小空间即可完成。通过「动态侧平板」「仰卧卷腹变式」等8组针对性动作，激活腹横肌与腹斜肌群，强化核心稳定性。\n\n动作编排规避俯卧撑/波比跳，采用低冲击力的音乐踩点训练，关节友好且易跟练。配合动感节奏完成3轮循环，感受深层肌肉的精准发力。每天抽一集剧的时间，就能雕刻马甲线基础轮廓！\n\n## 课程实际体验\n这套腰腹训练通过站立位动态侧屈 + 坐姿卷腹的组合，精准刺激腹横肌与腹斜肌。动作编排规避了腰椎压力大的动作，配合节奏明快的音乐，13分钟的训练完成度超高。\n\n练完能明显感受到深层肌群被唤醒，身体像被温柔地拧紧发条，新手也能安全解锁「核心发力感」！\n\n### 塑形操 · 腰腹训练入门课程演示视频\n<video controls src=\"https://v1.keepcdn.com/workout_video/compress/5bd18b59d734a26aa9e4cc8a_1280x720_1577329918128.mp4\" style=\"max-width:100%;\"></video>\n> 注：该视频链接提示系统内部异常，暂无法正常播放，建议稍后重试。', NULL, NULL, 1, '2026-02-27 05:29:10', 0, 0, 1, '2026-02-27 05:29:10', '2026-02-27 05:46:23', 0);
INSERT INTO `exercise` (`id`, `name`, `category`, `difficulty`, `equipment_required`, `description`, `cover_image_url`, `content_md`, `demo_video_url`, `demo_image_urls`, `publish_user_id`, `publish_time`, `like_count`, `comment_count`, `status`, `create_time`, `update_time`, `is_delete`) VALUES (26, '6 分钟瘦脸秘籍在此！面部瑜伽操，解锁紧致小 V 脸', '瑜伽', 'newbie', NULL, '', 'https://static1.keepcdn.com/2021/01/12/16/84ce4c028962d213b4c39c025f3ce8197022b483_562x316.jpg', 'https://www.calorietech.com/blog/plan/67f8c048708561000162e9b1?source=keep_web\n\n\nhttps://static1.keepcdn.com/2021/01/12/16/84ce4c028962d213b4c39c025f3ce8197022b483_562x316.jpg\n\nhttps://v1.keepcdn.com/media_composer/commonTranscode/commonTranscode_longFormVideo_720p_1683476510937.mp4', NULL, NULL, 1, '2026-02-27 05:30:45', 0, 0, 1, '2026-02-27 05:30:45', '2026-02-27 05:30:45', 0);
